// One-line item summary + count for the Airtable row.
const order = $('On New Shopify Order').item.json;
const lines = order.line_items || [];
const summary = lines.map(l => l.quantity + '× ' + l.title).join(', ');
return { json: { ...$json, item_count: lines.length, items: summary } };
